<script setup>
import {ref,onMounted,onBeforeUnmount,computed,nextTick} from 'vue';
import {categories,size} from '../lib/catalog';
import SearchDropdown from './SearchDropdown.vue';
import ChipInput from './ChipInput.vue';
import DropZone from './DropZone.vue';
import SettingsIcon from './SettingsIcon.vue';
const props=defineProps({avatars:{type:Array,default:()=>[]},tagOptions:{type:Array,default:()=>[]}});
const emit=defineEmits(['close','added']);
const dialog=ref(),discardDialog=ref(),nameInput=ref(),previewInput=ref(),filesInput=ref();
const name=ref(''),category=ref(''),avatars=ref([]),tags=ref([]),adult=ref(false),generic=ref(false),files=ref([]),busy=ref(false),error=ref(''),progress=ref(''),fileNotice=ref('');
const previewFile=ref(null),previewUrl=ref(''),token=ref('');let done=new Set(),previousFocus,discardFocus;
const frozen=computed(()=>busy.value||!!token.value);
const uploadFiles=computed(()=>previewFile.value?[new File([previewFile.value],'__preview.'+previewFile.value.name.split('.').pop().toLowerCase(),{type:previewFile.value.type}),...files.value]:files.value);
const valid=computed(()=>!!name.value.trim()&&!!category.value&&files.value.length>0);
const dirty=computed(()=>!!(name.value||files.value.length||previewFile.value||avatars.value.length||tags.value.length||generic.value||adult.value||category.value!==''));
const stateText=computed(()=>{if(busy.value)return progress.value||'Agregando…';const missing=[];if(!name.value.trim())missing.push('nombre');if(!category.value)missing.push('categoría');if(!files.value.length)missing.push('al menos un archivo');return missing.length?'Falta: '+missing.join(' y '):'Listo para agregar';});
const totalSize=computed(()=>files.value.reduce((sum,file)=>sum+file.size,0));
function clearPreview(){if(frozen.value)return;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewFile.value=null;}
function setPreview(file){if(frozen.value||!file)return;if(!/\.(png|jpe?g|webp)$/i.test(file.name)){fileNotice.value='La portada debe ser JPG, PNG o WebP.';return;}clearPreview();previewFile.value=file;previewUrl.value=URL.createObjectURL(file);fileNotice.value='';error.value='';}
function previewPicked(e){setPreview(e.target.files[0]);e.target.value='';}
function addFiles(incoming){if(frozen.value)return;const notices=[];for(const file of incoming){if(files.value.some(f=>f.name.toLocaleLowerCase()===file.name.toLocaleLowerCase())){notices.push('«'+file.name+'» ya está en la lista.');continue;}if(/\.(exe|msi|bat|cmd|ps1|com|scr|lnk)$/i.test(file.name)||!file.name.includes('.')){notices.push('«'+file.name+'» no es un formato de recurso compatible.');continue;}if(previewFile.value&&file.name.toLowerCase()==='__preview.'+previewFile.value.name.split('.').pop().toLowerCase()){notices.push('Ese nombre está reservado para la portada.');continue;}files.value.push(file);}fileNotice.value=notices.join(' ');if(!name.value&&files.value.length)name.value=files.value[0].name.replace(/\.[^.]+$/,'');}
function pick(e){addFiles([...e.target.files]);e.target.value='';}
function requestClose(){if(busy.value)return;if(!dirty.value){emit('close');return;}discardFocus=document.activeElement;discardDialog.value.showModal();}
function keepEditing(){discardDialog.value.close();discardFocus?.focus();}
function backdrop(e){if(e.target!==dialog.value)return;const rect=dialog.value.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)requestClose();}
function paste(event){if(frozen.value||discardDialog.value?.open||event.target.closest('input,textarea,[contenteditable="true"]'))return;const image=[...event.clipboardData.items].find(item=>item.type.startsWith('image/'));if(image){event.preventDefault();setPreview(image.getAsFile());}}
function keys(event){if(discardDialog.value?.open||!dialog.value?.open)return;if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();if(valid.value&&!busy.value)submit();}if(event.key==='Tab'){const controls=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled)')].filter(e=>e.getClientRects().length&&!e.hidden);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
async function request(url,options){const res=await fetch(url,options);const data=await res.json();if(!res.ok)throw Error(data.error||'No se pudo guardar');return data;}
async function submit(){if(busy.value||!valid.value)return;busy.value=true;error.value='';try{
if(!token.value){const data=await request('/api/upload/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value.trim(),category:category.value,avatars:avatars.value,tags:tags.value.join(', '),adult:adult.value,generic:generic.value,files:uploadFiles.value.map(f=>({name:f.name,size:f.size}))})});token.value=data.token;}
for(let i=0;i<uploadFiles.value.length;i++){const f=uploadFiles.value[i];if(done.has(f.name))continue;progress.value='Subiendo '+(i+1)+' de '+uploadFiles.value.length+': '+f.name;await request('/api/upload/file?token='+encodeURIComponent(token.value)+'&name='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f});done.add(f.name);}
progress.value='Guardando producto…';const result=await request('/api/upload/finish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token.value})});emit('added',result.path);
}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(async()=>{previousFocus=document.activeElement;dialog.value.showModal();document.addEventListener('paste',paste);document.addEventListener('keydown',keys);await nextTick();nameInput.value.focus();});
onBeforeUnmount(()=>{document.removeEventListener('paste',paste);document.removeEventListener('keydown',keys);if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);if(discardDialog.value?.open)discardDialog.value.close();if(dialog.value?.open)dialog.value.close();previousFocus?.focus();});
</script>
<template>
<dialog ref="dialog" class="add-product-dialog mochi-night" role="dialog" aria-modal="true" aria-labelledby="titulo-agregar" @cancel.prevent="requestClose" @click="backdrop"><form class="product-form" @submit.prevent="submit" :aria-busy="busy">
<header class="product-modal-header"><div><p>NUEVO EN TU BIBLIOTECA</p><h2 id="titulo-agregar">Agregar producto</h2></div><button type="button" class="product-icon-button" :disabled="busy" aria-label="Cerrar" @click="requestClose"><SettingsIcon name="x"/></button></header>
<div class="product-modal-body"><div class="product-modal-columns"><div class="product-cover-column"><label>Portada</label><DropZone cover :preview="previewUrl" :disabled="frozen" @pick="previewInput.click()" @files="setPreview($event[0])" @remove="clearPreview"/><input ref="previewInput" hidden type="file" accept="image/png,image/jpeg,image/webp" :disabled="frozen" @change="previewPicked"/><p class="product-paste-hint">También podés pegarla con <kbd>Ctrl+V</kbd></p><section class="product-files-section" aria-label="Archivos del producto"><DropZone :disabled="frozen" @pick="filesInput.click()" @files="addFiles"/><input ref="filesInput" hidden type="file" multiple :disabled="frozen" @change="pick"/><p v-if="fileNotice" class="product-inline-notice" role="status">{{fileNotice}}</p><template v-if="files.length"><p class="product-files-summary">{{files.length}} archivos · {{size(totalSize)}}</p><ul class="product-file-list"><li v-for="(file,index) in files" :key="file.name"><SettingsIcon :name="/\.(png|jpe?g|webp)$/i.test(file.name)?'image':/\.(zip|rar|7z|unitypackage)$/i.test(file.name)?'archive':'file'"/><span :title="file.name">{{file.name}}</span><small>{{size(file.size)}}</small><button type="button" class="product-icon-button" :disabled="frozen" :aria-label="'Quitar '+file.name" @click="files.splice(index,1)"><SettingsIcon name="x"/></button></li></ul></template></section></div>
<div class="product-fields"><label class="product-field" for="product-name"><span>Nombre <b>*</b></span><input id="product-name" ref="nameInput" v-model="name" required maxlength="180" :disabled="frozen" placeholder="Ej. Sakura Knit para Manuka" autofocus/></label>
<div class="product-field"><label>Categoría <b>*</b></label><SearchDropdown v-model="category" :options="Object.entries(categories).map(([value,label])=>({value,label}))" label="Categoría" placeholder="Seleccionar categoría" :disabled="frozen" night/></div>
<div class="product-field"><label>Avatares compatibles</label><ChipInput v-model="avatars" :options="props.avatars" label="Avatares compatibles" placeholder="Buscar avatares…" icon="search" :disabled="frozen||generic"/><small v-if="generic" class="product-field-note">Compatible con todos</small></div>
<div class="product-field"><label>Tags</label><ChipInput v-model="tags" :options="props.tagOptions" label="Tags" placeholder="Buscar o crear tag — Enter para agregar" icon="tag" allow-create :disabled="frozen"/></div>
<div class="product-options"><label><input type="checkbox" v-model="generic" :disabled="frozen"/><span><strong>Genérico</strong><small>Sirve para cualquier avatar</small></span></label><label><input type="checkbox" v-model="adult" :disabled="frozen"/><span><strong>R18</strong><small>Difumina la imagen del card</small></span></label></div></div></div>

</div>
<div v-if="error" class="product-error-strip" role="alert">{{error}}</div>
<footer class="product-modal-footer"><span aria-live="polite">{{stateText}}</span><button type="button" class="product-cancel" :disabled="busy" @click="requestClose">Cancelar</button><button type="submit" class="product-submit" :disabled="busy||!valid"><SettingsIcon v-if="busy" name="refresh" class="product-spinner"/>{{busy?'Agregando…':token?'Reintentar':'Agregar producto'}}<kbd v-if="!busy">Ctrl+↵</kbd></button></footer>
</form></dialog>
<dialog ref="discardDialog" class="product-discard-dialog mochi-night" aria-labelledby="discard-title" @cancel.prevent="keepEditing"><h3 id="discard-title">¿Descartar este producto?</h3><p>Tenés datos cargados. Si cerrás, perderás lo que todavía no guardaste.</p><p v-if="token">Los archivos que ya se enviaron permanecen en la carpeta de la biblioteca.</p><div><button type="button" class="product-cancel" @click="keepEditing">Seguir editando</button><button type="button" class="product-submit" @click="emit('close')">Descartar</button></div></dialog>
</template>
<style>
.add-product-dialog{width:860px;max-width:calc(100vw - 32px);max-height:calc(100dvh - 48px);margin:auto;padding:0;border:1px solid rgba(255,255,255,.08);border-radius:24px;background:var(--bg-modal);box-shadow:0 30px 90px rgba(0,0,0,.55);overflow:hidden}.add-product-dialog::backdrop,.product-discard-dialog::backdrop{background:rgba(10,6,16,.6)}.product-form{display:flex;flex-direction:column;max-height:calc(100dvh - 50px)}.product-modal-header{display:flex;align-items:center;justify-content:space-between;padding:24px 32px;border-bottom:1px solid var(--divider);flex:none}.product-modal-header p{font-size:11px;font-weight:700;letter-spacing:.1em;color:var(--accent);margin:0 0 9px}.product-modal-header h2{font-size:24px;font-weight:800;letter-spacing:-.6px;margin:0;color:var(--text)}
.add-product-dialog button,.product-discard-dialog button{font-family:inherit;cursor:pointer;box-sizing:border-box}.add-product-dialog button:focus-visible,.product-discard-dialog button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.add-product-dialog button:disabled{cursor:not-allowed;opacity:.5}.product-icon-button{display:flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;padding:0;border:0;border-radius:12px;background:rgba(255,255,255,.06);color:var(--text-soft)}.product-icon-button:hover{background:rgba(255,255,255,.1)}.product-modal-body{min-height:0;flex:1;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#6e567c transparent}.product-modal-columns{display:grid;grid-template-columns:240px minmax(0,1fr);gap:28px;padding:26px 32px}.product-cover-column>label,.product-field>label,.product-field>span,.product-categories legend{display:block;font-size:12px;font-weight:700;color:var(--text-muted);margin:0 0 10px}.product-field b{color:var(--accent);font-weight:700}.product-paste-hint{font-size:11px;line-height:1.8;color:var(--text-muted);margin:12px 0}.product-paste-hint kbd{font-family:'JetBrains Mono',monospace;font-size:10px;border:1px solid var(--border);border-radius:5px;padding:3px 5px;background:var(--surface)}.product-fields{display:flex;flex-direction:column;gap:20px;min-width:0}.product-field{display:block;min-width:0}.product-field>input{display:block;box-sizing:border-box;width:100%;height:48px;padding:0 14px;margin:0;background:var(--surface);border:1px solid var(--border);border-radius:12px;color:var(--text);font-family:inherit;font-size:15px;outline:none}.product-field>input::placeholder{color:var(--placeholder)}.product-field>input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(242,167,195,.2)}.product-field>input:disabled{opacity:.5}.product-field-note{display:block;margin-top:8px;font-size:11px;color:var(--accent)}
.product-categories{padding:0;margin:0;border:0;min-width:0}.product-categories legend{padding:0}.product-categories>div{display:flex;flex-wrap:wrap;gap:7px}.product-categories button{min-height:44px;padding:0 12px;border-radius:999px;border:1px solid rgba(255,255,255,.12);background:var(--surface-soft);color:var(--text-soft);font-size:11px;font-weight:500;line-height:1.5}.product-categories button[aria-pressed=true]{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:800}.product-categories button:hover:not(:disabled){border-color:var(--accent)}.product-options{display:grid;grid-template-columns:1fr 1fr;gap:10px}.product-options label{display:flex;align-items:center;gap:10px;min-height:76px;padding:12px 14px;border:1px solid var(--border);border-radius:12px;background:var(--surface-soft);cursor:pointer}.product-options input{width:16px;height:16px;min-width:16px;margin:0;flex:none;accent-color:var(--accent)}.product-options span{display:flex;flex-direction:column;gap:7px}.product-options strong{font-size:12px;font-weight:700}.product-options small{font-size:10px;color:var(--text-muted);line-height:1.6}
.product-files-section{padding:0 32px 26px}.product-files-summary{font-size:12px;color:var(--text-muted);margin:17px 0 9px}.product-file-list{margin:0;padding:0;list-style:none;max-height:200px;overflow:auto;scrollbar-width:thin;scrollbar-color:#6e567c transparent}.product-file-list li{display:flex;align-items:center;gap:10px;min-height:48px;border-bottom:1px solid var(--divider)}.product-file-list li>svg{flex:none;color:var(--accent);width:18px}.product-file-list li>span{font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--text-soft);flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.product-file-list li>small{font-size:11px;color:var(--text-muted);white-space:nowrap}.product-file-list .product-icon-button{background:none;margin-left:4px}.product-file-list .product-icon-button svg{width:16px;height:16px}.product-inline-notice{font-size:12px;color:var(--text-muted);line-height:1.7;margin:12px 0 0}.product-error-strip{padding:13px 32px;font-size:12px;line-height:1.7;background:rgba(242,167,195,.1);color:var(--accent);flex:none}
.product-modal-footer{display:flex;align-items:center;gap:12px;border-top:1px solid var(--divider);background:rgba(0,0,0,.15);padding:18px 32px;margin:0;flex:none;letter-spacing:normal}.product-modal-footer>span{min-width:0;flex:1;color:var(--text-muted);font-size:12px;line-height:1.6;overflow-wrap:anywhere}.product-cancel,.product-submit{display:flex;align-items:center;justify-content:center;gap:9px;min-height:48px;padding:0 18px;border-radius:12px;font-size:12px;font-family:inherit;white-space:nowrap}.product-cancel{border:1px solid rgba(255,255,255,.14);background:transparent;color:var(--text-soft)}.product-submit{border:1px solid var(--accent);background:var(--accent);color:var(--on-accent);font-weight:800}.product-submit kbd{font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:400;background:#2a142014;border-radius:5px;padding:4px}.add-product-dialog .product-submit:disabled{background:#5A4752;color:#D8CCD3;border-color:#5A4752;cursor:not-allowed;opacity:1}.product-submit:hover:not(:disabled){background:#f8bdd4}.product-cancel:hover:not(:disabled){background:var(--surface)}.product-spinner{width:17px;height:17px;animation:product-spin 1s linear infinite}@keyframes product-spin{to{transform:rotate(360deg)}}
.product-discard-dialog{width:420px;max-width:calc(100vw - 32px);padding:26px;border:1px solid var(--border);border-radius:20px;background:var(--bg-modal);box-shadow:0 25px 70px #0008}.product-discard-dialog h3{font-size:18px;margin:0 0 12px}.product-discard-dialog p{color:var(--text-muted);font-size:12px;line-height:1.8}.product-discard-dialog>div{display:flex;justify-content:flex-end;gap:10px;margin-top:23px}
@media(max-width:719px){.product-modal-columns{grid-template-columns:1fr;padding:22px;gap:24px}.product-cover-column{justify-self:center}.product-fields{width:100%}.product-modal-header{padding:22px}.product-files-section{padding:0 22px 22px}.product-modal-footer{padding:16px 22px;flex-wrap:wrap}.product-modal-footer>span{flex-basis:100%}.product-modal-footer .product-submit{flex:1}.product-modal-header h2{font-size:22px}.product-modal-header p{font-size:10px}.product-error-strip{padding:12px 22px}}
@media(prefers-reduced-motion:reduce){.product-spinner{animation:none}}
</style>


<style>
.product-cover-column{min-width:0}.product-cover-column .product-files-section{padding:0;margin-top:25px;width:240px}.product-cover-column .product-files-section .product-drop-button{flex-direction:column;text-align:center;gap:10px;padding:16px}.product-cover-column .drop-formats{display:none}.product-cover-column .product-files-section .drop-description strong{font-size:12px}.product-cover-column .product-files-section .drop-description small{font-size:11px}.product-cover-column .product-file-list li{gap:6px}.product-cover-column .product-file-list li>svg{width:15px}.product-cover-column .product-file-list li>span{font-size:10px}.product-cover-column .product-file-list li>small{font-size:10px}.product-cover-column .product-files-summary{font-size:11px}.product-fields .dropdown-trigger{height:48px;min-height:48px;background:var(--surface);border:1px solid var(--border);color:var(--text);font-size:14px;border-radius:12px}.product-fields .dropdown-trigger:focus-visible{border-color:var(--accent);box-shadow:0 0 0 3px rgba(242,167,195,.2)}
.product-category-menu.floating-dropdown-panel{background:#2b2138;border:1px solid var(--border);box-shadow:0 12px 35px #0007;color:var(--text)}.product-category-menu .dropdown-options>button{min-height:44px;color:var(--text-soft)}.product-category-menu .dropdown-options>button:hover,.product-category-menu .dropdown-options>button.selected{background:var(--accent-tint);color:var(--text)}.product-category-menu .dropdown-check{background:transparent;border-color:#9a8dab}.product-category-menu .dropdown-check.checked{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}.product-category-menu>input{background:var(--surface);border-color:var(--border);color:var(--text);height:44px}.product-category-menu .dropdown-done{min-height:44px;background:var(--surface);color:var(--text-soft)}
</style>
